PAGE = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tool Hub · Couchbase</title><link rel="icon" href="/assets/couchbase-favicon.svg"><link rel="stylesheet" href="/hub.css"></head><body>\n<header><a href="/" aria-label="Hotel concierge"><img src="/assets/couchbase-logo.svg" alt="Couchbase" width="150"></a><div><label for="mode">Data source</label><select id="mode"><option value="simulation">Simulation</option><option value="live">Live catalog</option></select><button id="theme" class="theme-switch" role="switch" aria-checked="false" aria-label="Dark mode"><span></span></button></div></header>\n<main><section class="hero"><div><p>HOTEL CONCIERGE</p><h1>Tool Hub</h1><p>Inspect the records. Try a function. Follow the result.</p></div><a class="hub-back" href="/"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>Back to concierge</a></section>\n<nav class="tabs" aria-label="Hub views"><button data-tab="catalog" aria-current="page">Catalog</button><button data-tab="history">Trace history</button><button data-tab="runner">Run function</button></nav><p id="status" role="status"></p>\n<section id="catalog"><div class="toolbar"><label>Find a record<input id="search" type="search" placeholder="Name or description"></label><label>Type<select id="kind"><option value="all">All records</option><option value="tool">Functions</option><option value="prompt">Policies</option></select></label><button id="refresh">Refresh</button></div><div class="catalog-layout"><div id="records" class="records" aria-label="Catalog records"></div><article id="record" class="detail"><h2>Select a record</h2></article></div></section>\n<section id="history" hidden><div class="toolbar"><h2>Request history</h2><button id="refresh-history">Refresh</button></div><p class="muted">Only this visitor’s records are shown.</p><div id="history-rows"></div></section>\n<section id="runner" hidden><div class="runner-grid"><article><h2>Run a function</h2><p class="muted">An isolated hotel sandbox. This does not change your concierge bookings or ask a model.</p><label>Function<select id="function"></select></label><label>Arguments (JSON)<textarea id="arguments" rows="8" spellcheck="false">{}</textarea></label><label>Starting context<select id="fixture"><option value="continue">Keep sandbox state</option><option value="empty">Reset to empty guest</option><option value="existing-stay">Reset to sample stay</option></select></label><button id="run" class="primary">Run function</button></article><article><h2>Result</h2><p id="run-status" role="status">Choose a function and supply its arguments.</p><pre id="result">{}</pre><h3>Execution trace</h3><div id="run-trace"></div></article></div></section>\n</main><footer>Hotel Tool Hub <a href="https://github.com/john-couchbase/couchbase-hotel-concierge">GitHub</a></footer><script src="/tool-manifest.js"></script><script src="/policy-manifest.js"></script><script src="/hub.js"></script></body></html>\n'
